/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import java.io.BufferedReader;import java.io.File;import java.io.FileReader;import java.util.ArrayList;import java.util.Arrays;import java.util.HashMap;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;import java.util.Set;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.core.io.ClassPathResource;import org.springframework.core.io.Resource;import page2020.Data;import page2020.unit.Func;import page2020.unit.Menu;import page2020.util.EmptyUtil;import page2020.view.Text;import page2020.view.bs4.B4button;import page2020.view.css3.C3color.White;public class App extends Name<App> {	public static final boolean first_user = false;	private class Doc {		private static final String PAGE = "page.";		private static final String APP = "app.";		private static final String DATA = "data."; 		private static final String ICON = ".icon";		private static final String SUB = ".sub";		private static final String COLOR = ".color";		private static final String BUTTON = ".button";		private static final String OUTLINE = ".outline";		private static final String MENU = "menu.";		private static final String LINK = ".link";		private static final String ITEM = ".item.";		private static final String TIP = ".tip";		private static final String ANNEX = ".annex";	}	private static Page page = new Page()			.icon("secure2020-32x32.png", "secure2020-192x192.png", "secure2020-180x180.png")			.logo("secure2020-logo-sm.png", "secure2020-logo-md.jpg", "secure2020-logo-lg.jpg")			.color(White.White, White.White, White.White, White.White)			.zoom(0.75);	public static Data data = new Data();	private static Map<String, Page> sysPageMap = new HashMap<String, Page>();	private static Map<String, Data> sysDataMap = new HashMap<String, Data>();	public static Prop<App, Func> funcProp = new Prop<App, Func>();	public static Prop<App, Menu> menuProp = new Prop<App, Menu>();	private static Map<String, Menu> menuTree = new LinkedHashMap<String, Menu>();	private static Prop<App, String> classProp = new Prop<App, String>();	private static Prop<App, LinkedHashMap<String, Object>> fieldProp = new Prop<App, LinkedHashMap<String, Object>>();	private static Prop<App, LinkedHashMap<String, Object>> itemProp = new Prop<App, LinkedHashMap<String, Object>>();	private static Prop<App, String> tipProp = new Prop<App, String>();	private static Prop<App, String> annexProp = new Prop<App, String>();	private static Map<String, B4button> buttonMap = new LinkedHashMap<String, B4button>();	private static Map<String, Text> iconMap = new LinkedHashMap<String, Text>();	static {		Map<String, String> document = document();		app(document);		menu(document);		data(document);		buttons(document);		icons(document);		groupMenus();	}	public static Set<String> sysCodeSet() {		return sysPageMap.keySet();	}	public static String sysCodeKey(String sysCode) {		if (sysPageMap.keySet().contains(sysCode)) {			return Doc.APP + sysCode;		}		return null;	}	public static Page sysPage(String sysCode) {		if (EmptyUtil.not(sysCode) && sysPageMap.keySet().contains(sysCode)) {			return sysPageMap.get(sysCode);				}		return null;	}	public static Page page(String sysCode) {		if (EmptyUtil.not(sysCode) && sysPageMap.keySet().contains(sysCode)) {			return sysPageMap.get(sysCode).copy();				} else {			return page.copy();				}	}	public static B4button button(String btnName) {		B4button button = buttonMap.get(btnName);		if (button != null) {			return button.copy();			}		return null;	}	public static Text icon(String name) {		Text text = iconMap.get(name);		if (text != null) {			return text.copy();				}		return null;	}	public static Menu menuTree(String sysCode) {		if (menuTree.containsKey(sysCode)) {			return menuTree.get(sysCode).copy();			}		return null;	}	public static Menu menu(String name) {		if (menuProp.hasKey(name)) {			return menuProp.value(name);			}		return null;	}	public static Func function(String name) {		if (EmptyUtil.not(name) && name.length() >= 1) {			String code = name.substring(1).replaceAll("/", "\\.");			if (funcProp.hasKey(code)) {				return funcProp.value(code);				}		}		return null;	}	public static Data data(String sysCode) {		if (sysDataMap.keySet().contains(sysCode)) {			return sysDataMap.get(sysCode);		}		return data;	}	public static String className(Class<?> clazz) {		String simple = clazz.getSimpleName();		if (classProp.hasKey(simple)) {			return simple;		}		String canonical = clazz.getCanonicalName();		if (classProp.hasKey(canonical)) {			return canonical;		}		return simple;	}	public static String classKey(String name) {		return (classProp.hasKey(name)) ? Doc.DATA + name : null;	}	public static String classKey(Class<?> clazz) {		return classKey(className(clazz));	}	public static String classValue(String name) {		return (classProp.hasKey(name)) ? classProp.value(name) : null;	}	public static String classValue(Class<?> clazz) {		return classValue(className(clazz));	}	public static String fieldKey(String className, String fieldName) {		return (fieldProp.hasKey(className) && fieldProp.value(className).containsKey(fieldName))			? (Doc.DATA + className + "." + fieldName) : null;	}	public static String fieldKey(Class<?> clazz, String fieldName) {		return fieldKey(className(clazz), fieldName);	}	public static String fieldValue(String className, String fieldName) {		return (fieldProp.hasKey(className)) ? (String) fieldProp.value(className).get(fieldName) : null;	}	public static String fieldValue(Class<?> clazz, String fieldName) {		return fieldValue(className(clazz), fieldName);	}	public static boolean hasItemKey(String datalistKey) {		return itemProp.hasKey(datalistKey);	}	public static boolean hasItemKey(String className, String fieldName) {		return itemProp.hasKey(className + "." + fieldName);	}	public static boolean hasItemKey(Class<?> clazz, String fieldName) {		return itemProp.hasKey(className(clazz) + "." + fieldName);	}	public static String itemKey(String datalistKey, String itemName) {				return (itemProp.hasKey(datalistKey)) ? (Doc.DATA + datalistKey + Doc.ITEM + itemName) : null; 	}	public static String itemKey(String className, String fieldName, String itemName) {		return itemKey(className + "." + fieldName, itemName);	}	public static String itemKey(Class<?> clazz, String fieldName, String itemName) {		return itemKey(className(clazz) + "." + fieldName, itemName);	}	public static LinkedHashMap<String, Object> itemValue(String datalistKey) {		return itemProp.value(datalistKey);	}		public static LinkedHashMap<String, Object> itemValue(String className, String fieldName) {		return itemProp.value(className + "." + fieldName);	}	public static LinkedHashMap<String, Object> itemValue(Class<?> clazz, String fieldName) {		return itemValue(className(clazz), fieldName);	}	public static String tipKey(String className, String fieldName) {		String key = className + "." + fieldName;		return (tipProp.hasKey(key)) ? (Doc.DATA + key + Doc.TIP) : null;	}	public static String tipKey(Class<?> clazz, String fieldName) {		return tipKey(className(clazz), fieldName);	}	public static String tipValue(String className, String fieldName) {		return tipProp.value(className + "." + fieldName);	}	public static String tipValue(Class<?> clazz, String fieldName) {		return tipValue(className(clazz), fieldName);	}	public static String annexKey(String className, String fieldName) {		String key = className + "." + fieldName;		return (annexProp.hasKey(key)) ? (Doc.DATA + key + Doc.ANNEX) : null;	}	public static String annexKey(Class<?> clazz, String fieldName) {		return annexKey(className(clazz), fieldName);	}	public static String annexValue(String className, String fieldName) {		return annexProp.value(className + "." + fieldName);	}	public static String annexValue(Class<?> clazz, String fieldName) {		return annexValue(className(clazz), fieldName);	}	private static Logger log = LoggerFactory.getLogger(App.class);	private static Map<String, String> document() {		Map<String, String> document = new LinkedHashMap<String, String>();		try {			Resource resource = new ClassPathResource("messages.properties");			File file = resource.getFile();			BufferedReader reader = new BufferedReader(new FileReader(file));			String line = null;			while ((line = reader.readLine()) != null) {				line = line.trim();				if (line.length() == 0 || line.startsWith("#") || line.contains("=") == false) {					continue;				}				String key = null;				String value = null;				if (! line.endsWith("=")) {					String[] tokens = line.split("=");					key = tokens[0].trim();					value = tokens[1].trim();				} else {					key = line;					value = "";				}				if (EmptyUtil.not(key)) {					document.put(key, value);				}			}			reader.close();			if (Log.app) {				log.info("document: messages.properties=" + document.size());			}			} catch (Exception ex) {			log.error("document: " + ex.toString());			document = null;		}		return document;			}	private static void app(Map<String, String> document) {		for (String key : document.keySet()) {			if (! key.startsWith(Doc.APP)) {				continue;			}			String keyword = lastword(key);			int level = level(keyword);			if (level == 0) {				if (! sysPageMap.containsKey(keyword)) {					sysPageMap.put(keyword, page.copy());					sysDataMap.put(keyword, new Data());					Func func = new Func().name(keyword);					func.setSysCode(keyword);					func.setCode(key);					func.setAction("./" + keyword);					funcProp.add(keyword, func);				}				continue;			}			boolean icon = keyword.endsWith(Doc.ICON);			boolean sub = keyword.endsWith(Doc.SUB);			boolean button = keyword.endsWith(Doc.BUTTON);			if (! (icon || button)) {				String sysCode = firstword(keyword);				if (sysPageMap.containsKey(sysCode) && (! funcProp.hasKey(keyword))) {					Func func = new Func().name(keyword);						func.setSysCode(sysCode);						func.setCode(key);								func.setAction("./" + keyword.replaceAll("\\.", "/"));						funcProp.add(keyword, func);				}			}			Func func = funcProp.value(preword(keyword));			if (func == null) {				continue;			}			if (icon) {				func.setIcon(document.get(key));				continue;			}			if (sub) {				func.setSubCode(key);				continue;			}			if (button) {				Arrays.asList(document.get(key).split(",")).forEach(item -> func.getButtons().add(item.trim()));			}		}		if (Log.app) {			int count = sysDataMap.size();			log.info("App.sysData = " + count);			int i = 0;			for (String key : sysDataMap.keySet()) {				log.info("App.sysData[" + (i++) + "] = " + key);			}			count = funcProp.count();			log.info("App.funcProp = " + count);			i = 0;			for (String key : funcProp.keys()) {				Func func = funcProp.value(key);				StringBuilder sb1 = new StringBuilder().append(func.getName());				if (EmptyUtil.not(func.getIcon())) {					sb1.append(" (" + document.get(func.getIcon()) + ")");				}				log.info("App.funcProp[" + i + "] = " + sb1.toString());				if (func.getButtons().size() > 0) {					log.info("App.funcProp[" + i + "].button = " + func.getButtons().toString());				}				i++;			}		}	}	private static void menu(Map<String, String> document) {		for (String key : document.keySet()) {			if (! key.startsWith(Doc.MENU)) {				continue;			}			String keyword = lastword(key);			String sysCode = firstword(keyword);			boolean link = keyword.endsWith(Doc.LINK);			if ((! menuProp.hasKey(sysCode)) && (! sysCode.equals(keyword))) {				Menu menu = new Menu().name(sysCode);				menu.setSysCode(sysCode);				menu.setParent(null);				menu.setLevel(0);				menu.setCode(Doc.APP + sysCode);							}			if (! link) {				if (! menuProp.hasKey(keyword)) {					Menu menu = new Menu().name(keyword);					menu.setSysCode(sysCode);					menu.setParent(preword(keyword));					menu.setLevel(level(keyword));					menu.setCode(key);					menuProp.add(keyword, menu);									}				continue;			}			Menu menu = menuProp.value(preword(keyword));			if (menu != null) {				String[] tokens = document.get(key).split(",");				for (int i=0; i < tokens.length; i++) {					String name = sysCode + "." + tokens[i].trim();					Func func = funcProp.value(name);					if (func != null) {						menu.getFuncList().add(func);					}				}			}		}		if (Log.app) {			int count = menuProp.count();			log.info("App.menuProp = " + count);			for (int i=0; i < count; i++) {				Menu menu = menuProp.value(i);				log.info("App.menuProp[" + i + "] = " + menu.getName() + " (" + menu.getLevel() + ")");				if (menu.getFuncList().size() > 0) {					List<String> links = new ArrayList<String>();					menu.getFuncList().forEach(func -> links.add(func.getName()));					log.info("App.menuProp[" + i + "].link = " + links.toString());				}			}		}	}	private static void data(Map<String, String> document) {		for (String key : document.keySet()) {			if (! key.startsWith(Doc.DATA)) {				continue;			}			String keyword = lastword(key);			boolean item = false;			if (keyword.contains(Doc.ITEM)) {				int pos = keyword.lastIndexOf(Doc.ITEM) + Doc.ITEM.length();				String lastword = keyword.substring(pos);				if (! lastword.contains(".")) {					item = true;				}			}			boolean tip = keyword.endsWith(Doc.TIP);			boolean annex = keyword.endsWith(Doc.ANNEX);			if (! (item || tip || annex)) {				String preword = preword(keyword);				if (preword == null || (! classProp.hasKey(preword))) {					classProp.add(keyword, document.get(key));					fieldProp.add(keyword, new LinkedHashMap<String, Object>());				} else {					String[] tokens = key.split("\\.");					fieldProp.value(preword).put(tokens[tokens.length - 1], document.get(key));				}				continue;			}			if (item) {				int pos = keyword.lastIndexOf(Doc.ITEM);				String field = keyword.substring(0, pos);				String itemKey = keyword.substring(pos + Doc.ITEM.length());				LinkedHashMap<String, Object> items = itemProp.value(field);				if (items == null) {					items = new LinkedHashMap<String, Object>();					itemProp.add(field, items);				}				items.put(itemKey, document.get(key));				continue;			}			String preword = preword(keyword);			if (tip) {				tipProp.add(preword, document.get(key));				continue;			}			if (annex) {				annexProp.add(preword, document.get(key));				continue;			}		}		if (Log.app) {			int count = classProp.count();			log.info("App.classProp = " + count);			for (int i=0; i < count; i++) {				String classKey = classProp.key(i);				log.info("App.classProp[" + i + "] = " + classKey);				LinkedHashMap<String, Object> fields = fieldProp.value(classKey);				if (fields != null) {					int count2 = fields.size();					log.info("App.fieldProp[" + classKey + "] = " + count2);					int j = 0;					for (String fieldKey : fields.keySet()) {						log.info("App.fieldProp[" + classKey + "][" + (j++) + "] = " + fieldKey);						String preword = classKey + "." + fieldKey;						LinkedHashMap<String, Object> items = itemProp.value(preword);						if (items != null) {							int count3 = items.size();							log.info("App.itemProp[" + preword + "] = " + count3);							for (String itemKey : items.keySet()) {								log.info("App.itemProp[" + preword + "][" + itemKey + "] = " + items.get(itemKey));							}						}						if (tipProp.hasKey(preword)) {							log.info("App.tipProp[" + preword + "] = " + tipProp.value(preword));						}						if (annexProp.hasKey(preword)) {							log.info("App.annexProp[" + preword + "] = " + annexProp.value(preword));						}					}				}			}					}	}	private static void buttons(Map<String, String> document) {		for (String key : document.keySet()) {			if (! key.startsWith(Doc.PAGE)) {				continue;			}			if (! (key.contains(Doc.BUTTON) || (key.contains(Doc.OUTLINE)))) {				continue;			}			String keyword = lastword(key);			boolean button = keyword.endsWith(Doc.BUTTON) || keyword.endsWith(Doc.OUTLINE);			boolean icon = keyword.endsWith(Doc.ICON);			boolean color = keyword.endsWith(Doc.COLOR);			if (button) {				buttonMap.put(keyword, (B4button) new B4button().name(keyword).code(key));				continue;			}			if (icon) {				B4button b4button = buttonMap.get(preword(keyword));				if (b4button != null) {					((Text) b4button.get(0)).icon(document.get(key));				}				continue;			}			if (color) {				B4button b4button = buttonMap.get(preword(keyword));				if (b4button != null) {					b4button.cssClass(document.get(key));				}				continue;			}		}		if (Log.app) {			int index = 0;			for (String name : buttonMap.keySet()) {				log.info("App.buttons[" + (index++) + "]=" + name);			}		}	}	private static void icons(Map<String, String> document) {		for (String key : document.keySet()) {			if (! key.startsWith(Doc.PAGE)) {				continue;			}			if (! key.endsWith(Doc.ICON)) {				continue;			}			String keyword = lastword(preword(key));			iconMap.put(keyword, new Text().icon(document.get(key)));		}		if (Log.app) {			int index = 0;			for (String name : iconMap.keySet()) {				log.info("App.icons[" + (index++) + "]=" + name);			}		}		}	private static void groupMenus() {		int size = menuProp.count();		for (int i=0; i < size; i++) {			boolean top = false;			Menu menu = menuProp.value(i);			if (menu.getLevel() == 0) {				menuTree.put(menu.getName(), menu);				top = true;			}			if (! top) {				Menu parent = menuProp.value(menu.getParent());				if (parent != null) {					parent.getChildren().add(menu);				}			}			if (! menu.getFuncList().isEmpty()) {				menu.getFuncList().forEach(func -> {					if (EmptyUtil.is(func.getMenu())) {						func.setMenu(menu.getName());					}				});			}		}		if (Log.app) {			if (! menuTree.isEmpty()) {				log.info("App.menuTree=" + menuTree.keySet().toString());			}		}		}	private static int level(String key) {		int count = 0;		int len = key.length();		for (int i=0; i < len; i++) {			if (key.charAt(i) == '.') {				count += 1;			}		}		return count;	}	private static String firstword(String key) {		if (! key.contains(".")) {			return key;		}		return key.split("\\.")[0];	}	private static String lastword(String key) {		int beginIndex = key.indexOf(".");		if (beginIndex > 0) {			return key.substring(beginIndex + 1);		}		return null;	}	private static String preword(String key) {		int endIndex = key.lastIndexOf(".");		if (endIndex > 0) {			return key.substring(0, endIndex);		}		return null;	}	private String appCode;	private String sysCode;	private String clsCode;	private String base;	public App(String name, String path) {		this.parseName(name, path);		this.parseSysCode();		this.parseClsCode(name);		this.parseBase();		if (! (funcProp.hasKey(this.appCode) || (sysDataMap.get(this.sysCode) != null))) {			log.error("App: '" + Doc.APP + this.appCode + "' is NOT in messages.properties !");		}				if (Log.app) {			log.info(this.toString());		}	}	@Override	public String toString() {		return "App [name=" + super.getName() + ", appCode=" + appCode + ", sysCode=" 			+ sysCode + ", clsCode=" + clsCode + ", base=" + base + "]";	}	private void parseName(String name, String path) {		if (! name.startsWith("/")) {			name = "/" + name;		}		if (EmptyUtil.is(path) || SysKey.def.equals(path)) {			path = "";		} else if (! path.startsWith("/")) {			path = "/" + path;		}		super.name(name + path);	}	private void parseSysCode() {		this.appCode = super.getName().substring(1).replaceAll("/", ".");		if (this.appCode.contains(".")) {			String[] tokens = this.appCode.split("\\.");			this.sysCode = tokens[0];		} else {			this.sysCode = this.appCode;			}	}	private void parseClsCode(String name) {		int pos = name.indexOf(this.sysCode) + this.sysCode.length();		if (pos < name.length()) {			String clsCode = name.substring(pos);			if (clsCode.startsWith("/")) {				clsCode = clsCode.substring(1);			}			this.clsCode = clsCode;		} else {			this.clsCode = "";		}	}	private void parseBase() {		String base = "./";		int len = this.appCode.length();		for (int i=0; i < len; i++) {			if (this.appCode.charAt(i) == '.') {				base += "../";			}		}		this.base = base;	}	public String getAppCode() {		return appCode;	}	public void setAppCode(String appCode) {		this.appCode = appCode;	}	public String getSysCode() {		return sysCode;	}	public void setSysCode(String sysCode) {		this.sysCode = sysCode;	}	public String getClsCode() {		return clsCode;	}	public void setClsCode(String clsCode) {		this.clsCode = clsCode;	}	public String getBase() {		return base;	}	public void setBase(String base) {		this.base = base;	}}